#include <iostream>
#include <queue>
#include <string>
using namespace std;

struct Connection { int id; queue<string> inbox; queue<string> outbox; };

class TcpServer {
    queue<Connection*> pending;
public:
    void accept(Connection* conn) {
        cout << "Connection " << conn->id << " accepted" << endl;
        pending.push(conn);
    }
    void process() {
        while (!pending.empty()) {
            auto conn = pending.front(); pending.pop();
            while (!conn->inbox.empty()) {
                string msg = conn->inbox.front(); conn->inbox.pop();
                cout << "Received from " << conn->id << ": " << msg << endl;
                conn->outbox.push("Echo: " + msg);
            }
            while (!conn->outbox.empty()) {
                cout << "Sent to " << conn->id << ": " << conn->outbox.front() << endl;
                conn->outbox.pop();
            }
        }
    }
};

int main() {
    TcpServer server;
    Connection c1{1}, c2{2};
    c1.inbox.push("Hello");
    c2.inbox.push("World");
    c2.inbox.push("C++");
    server.accept(&c1);
    server.accept(&c2);
    server.process();
    return 0;
}
